CREATE TABLE "public"."examples" (
  "id"               bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "definition_id"    bigint,
  "user_id"          uuid,
  "sentence_text"    text                     NOT NULL,
  "translation_text" text,
  "vote_score"       integer                  DEFAULT 0,
  "created_at"       timestamp with time zone DEFAULT now(),
  "updated_at"       timestamp with time zone DEFAULT now(),
  CONSTRAINT "examples_definition_id_fkey" FOREIGN KEY (definition_id) REFERENCES public.definitions(id) ON DELETE CASCADE,
  CONSTRAINT "examples_pkey" PRIMARY KEY (id),
  CONSTRAINT "examples_user_id_fkey" FOREIGN KEY (user_id) REFERENCES public.profiles(id)
);

CREATE TRIGGER set_timestamp_examples
  BEFORE UPDATE ON public.examples
  FOR EACH ROW
  EXECUTE FUNCTION public.update_timestamp();

REVOKE ALL ON SEQUENCE "public"."examples_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."examples_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."examples_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."examples_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."examples_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."examples_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."examples_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."examples_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."examples" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."examples" TO "service_role";

REVOKE ALL ON TABLE "public"."examples" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."examples" TO "postgres";
